import json, urllib.parse, urllib.request
base='http://10.139.194.154:3080/v3/projects/CampusNetwork_04/nodes/{}/command?cmd={}'
queries={
'GUEST_WIFI_CLIENT01':['ping 200.200.200.100','ipconfig','show ip','display ip interface brief','display current-configuration'],
'Outside_FTP_Client01':['ipconfig','show ip','display ip interface brief','display current-configuration'],
}
for node,cmds in queries.items():
  for cmd in cmds:
    url=base.format(urllib.parse.quote(node,safe=''),urllib.parse.quote(cmd,safe=''))
    try:
      data=json.load(urllib.request.urlopen(url,timeout=20))
      print(f'===== {node} :: {cmd} =====')
      print(data.get('output',''))
    except Exception as e: print(node,cmd,e)
PY","cwd":"/workspace/output/agent_core/GPT-5.6-Sol-Pro/q0017/workspace","description":"Query endpoint IP and ping outputs","run_in_background":false,"stdin":null,"timeout":300000}}

{"name":"Bash","arguments":{"command":"PYTHONPATH="." python - <<'PY'
import json, urllib.parse, urllib.request
nodes=['AGG_SW_01','AGG_SW_02','AGG_SW_03','AGG_SW_04','Core_SW_01','Core_SW_02','FW_01','FW_02','BJHQ_CSR1000V_GW_01','ChinaUnicom_SW','GUEST_WIFI_CLIENT01']
cmds=['display current-configuration','display ip interface brief','display ip routing-table','display interface brief','display interface']
base='http://10.139.194.154:3080/v3/projects/CampusNetwork_04/nodes/{}/command?cmd={}'
for node in nodes:
  for cmd in cmds:
    url=base.format(node,urllib.parse.quote(cmd,safe=''))
    try:
      d=json.load(urllib.request.urlopen(url,timeout=20)); out=d.get('output','')
      if out and 'not found in mock data' not in out:
        print(f'===== {node} :: {cmd} =====\n{out}')
    except Exception: pass
PY","cwd":"/workspace/output/agent_core/GPT-5.6-Sol-Pro/q0017/workspace","description":"Collect path device configurations","run_in_background":false,"stdin":null,"timeout":300000}}

